using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class NewGameCombatTests
{
    static WorldSession Start()=>NewGameWorldTests.Session([NewGameWorldTests.Officer(site:"site:kofu",role:StartTemplate.Retainer,lord:"person:shingen")]);
    static void At(WorldSession s,long t)=>NewGameWorldTests.At(s,t);
    static void Open(WorldSession s){foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,m.Id,s.Revision).Code);}
    static NewMilitaryInput Input(WorldSession s,NewMilitaryAction a)=>new(new("request:combat/"+s.Revision+"/"+a),a);
    static void Send(WorldSession s,NewMilitaryAction a,long amount=0){var r=s.DecideNewMilitary(Input(s,a) with{Amount=amount},s.PlayerControl,s.Revision);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);}
    static WorldSession Ready(){var s=Start();Send(s,NewMilitaryAction.Request);At(s,2);Open(s);Send(s,NewMilitaryAction.Accept);At(s,4);Open(s);Send(s,NewMilitaryAction.Pickup);Send(s,NewMilitaryAction.Load,100000);Send(s,NewMilitaryAction.Deploy);return s;}
    static void Permit(WorldSession s){Send(s,NewMilitaryAction.CombatPermit);At(s,s.Seconds+2);Open(s);}
    [Fact]public void LoanPermissionDoesNotAuthorizeCombat(){var s=Ready();Assert.False(NewGameMilitary.CanStartCombat(s.DiagnosticSnapshot()));Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(Input(s,NewMilitaryAction.CombatStart),s.PlayerControl,s.Revision).Code);}
    [Fact]public void PhysicalPermissionMustBeOpened(){var s=Ready();Send(s,NewMilitaryAction.CombatPermit);At(s,s.Seconds+2);Assert.Contains(s.DiagnosticSnapshot().NewMilitary!.Events,e=>e.Effect==MilitaryEffect.CombatPermission);Assert.False(NewGameMilitary.CanStartCombat(s.DiagnosticSnapshot()));Open(s);Assert.True(NewGameMilitary.CanStartCombat(s.DiagnosticSnapshot()));}
    [Fact]public void PermitDoesNotGenerateLossesBeforeContact(){var s=Ready();Permit(s);At(s,s.Seconds+4);Assert.Empty(NewGameMilitary.CombatLosses(s.DiagnosticSnapshot(),s.Seconds));Assert.Equal(100,NewGameMilitary.TotalStrength(s.DiagnosticSnapshot(),s.Seconds));}
    [Fact]public void CombatLossesAndSupplyUseSameClock(){var s=Ready();Permit(s);Send(s,NewMilitaryAction.CombatStart);long t=s.Seconds;var before=NewGameMilitary.View(s.DiagnosticSnapshot()).Carry;At(s,t+1);var w=s.DiagnosticSnapshot();Assert.Equal(90,NewGameMilitary.TotalStrength(w,s.Seconds));Assert.Equal(100,before-NewGameMilitary.View(w).Carry);At(s,t+2);Assert.Equal(190,before-NewGameMilitary.View(s.DiagnosticSnapshot()).Carry);Assert.Equal(90,s.DiagnosticSnapshot().NewMilitary!.Uses.Last().Soldiers);}
    [Fact]public void EndingCombatDoesNotRestoreLostSoldiers(){var s=Ready();Permit(s);Send(s,NewMilitaryAction.CombatStart);At(s,s.Seconds+3);Send(s,NewMilitaryAction.CombatEnd);int men=NewGameMilitary.TotalStrength(s.DiagnosticSnapshot(),s.Seconds);At(s,s.Seconds+5);Assert.Equal(men,NewGameMilitary.TotalStrength(s.DiagnosticSnapshot(),s.Seconds));Assert.All(s.DiagnosticSnapshot().Characters,c=>Assert.Equal(LifeState.Adult,c.Life));}
    [Fact]public void CombatPermissionExpiresWithoutTimeReinterpretation(){var s=Ready();Permit(s);At(s,s.Seconds+NewGameMilitary.CombatPermitDuration);Assert.False(NewGameMilitary.CanStartCombat(s.DiagnosticSnapshot()));}
    [Fact]public void ReturnWishPreventsNewEngagement(){var s=Ready();Permit(s);Send(s,NewMilitaryAction.Return);Assert.False(NewGameMilitary.CanStartCombat(s.DiagnosticSnapshot()));}
    [Fact]public void ReplayInputCannotDuplicateContact(){var s=Ready();Permit(s);var i=Input(s,NewMilitaryAction.CombatStart);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(i,s.PlayerControl,s.Revision).Code);At(s,s.Seconds+2);var hash=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.Equal(ResultCode.AlreadyAccepted,s.DecideNewMilitary(i,s.PlayerControl,0).Code);Assert.Equal(hash,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(3)][InlineData(10)]
    public void SaveRestorationHasIdenticalContactFuture(int offset){var s=Ready();Permit(s);Send(s,NewMilitaryAction.CombatStart);At(s,s.Seconds+offset);var copy=new WorldSession(ContractJson.Read<ContractWorld>(ContractJson.Write(s.DiagnosticSnapshot())));foreach(var x in new[]{s,copy}){At(x,x.Seconds+2);Send(x,NewMilitaryAction.CombatEnd);Send(x,NewMilitaryAction.Report);At(x,x.Seconds+2);Open(x);}Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(copy.DiagnosticSnapshot()));}
    [Fact]public void ImmutableReportContainsOwnDispatchedCountOnly(){var s=Ready();Permit(s);Send(s,NewMilitaryAction.CombatStart);At(s,s.Seconds+1);Send(s,NewMilitaryAction.Report);var w=s.DiagnosticSnapshot();var report=w.NewMilitary!.Reports.Last();Assert.Equal(90,report.Soldiers);var body=w.Messaging.Messages.Single(m=>m.Id==report.Message).Body;Assert.DoesNotContain("exercise",body);At(s,s.Seconds+3);Assert.Equal(body,s.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Id==report.Message).Body);}
    [Fact]public void RecallStopsFurtherContactAndMovesPhysically(){var s=Ready();Permit(s);Send(s,NewMilitaryAction.CombatStart);At(s,s.Seconds+1);Send(s,NewMilitaryAction.CombatEnd);Send(s,NewMilitaryAction.Recall);At(s,s.Seconds+2);Assert.False(NewGameMilitary.CombatActive(s.DiagnosticSnapshot()));}
    [Fact]public void ForgingRestoredStrengthIsRejected(){var s=Ready();Permit(s);Send(s,NewMilitaryAction.CombatStart);At(s,s.Seconds+1);var w=s.DiagnosticSnapshot();w.Units[0]=w.Units[0] with{Soldiers=40};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void InquiryCanExplainUnopenedOriginalWithoutForgingOpening(){var s=Ready();Send(s,NewMilitaryAction.CombatPermit);At(s,s.Seconds+2);var original=s.DiagnosticSnapshot().NewMilitary!.Events.Single(e=>e.Effect==MilitaryEffect.CombatPermission).Message;Send(s,NewMilitaryAction.Inquire);At(s,s.Seconds+2);var reply=s.DiagnosticSnapshot().NewMilitary!.Events.Last(e=>e.Effect==MilitaryEffect.StatusSent).Message;Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,new(reply),s.Revision).Code);Assert.True(NewGameMilitary.CanStartCombat(s.DiagnosticSnapshot()));Assert.DoesNotContain(s.DiagnosticSnapshot().NewMilitary!.Openings,o=>o.Message==original);}
    [Fact]public void PermitOriginalBindsActorTargetPeriodAndBasis(){var s=Ready();Permit(s);var w=s.DiagnosticSnapshot();var e=w.NewMilitary!.Events.Single(e=>e.Effect==MilitaryEffect.CombatPermission);var m=w.Messaging.Messages.Single(m=>m.Id==e.Message);var permit=ContractJson.Read<MilitaryNotice>(System.Text.Encoding.UTF8.GetBytes(m.Body)).Combat!;Assert.Equal(w.PlayerControl,permit.Agent);Assert.Equal(w.NewMilitary.Terms.Principal,permit.Principal);Assert.Equal(new EntityId("exercise:local-contact"),permit.Target);Assert.Equal(e.At+120,permit.Until);Assert.Equal(w.NewMilitary.Terms.Case,permit.Basis);}
    [Fact]public void OldNoticeStillOmitsOptionalCombatField(){var text=System.Text.Encoding.UTF8.GetString(ContractJson.Write(new MilitaryNotice(MilitaryEffect.Permission,"original",1,null)));Assert.DoesNotContain("Combat",text);Assert.Null(ContractJson.Read<MilitaryNotice>(System.Text.Encoding.UTF8.GetBytes(text)).Combat);}
    [Fact]public void ExpiredPermissionStopsAlreadyStartedContact(){var s=Ready();Permit(s);long expiry=s.DiagnosticSnapshot().NewMilitary!.Events.Single(e=>e.Effect==MilitaryEffect.CombatPermission).At+NewGameMilitary.CombatPermitDuration;At(s,expiry-1);Send(s,NewMilitaryAction.CombatStart);At(s,expiry+2);Assert.False(NewGameMilitary.CombatActive(s.DiagnosticSnapshot()));Assert.All(NewGameMilitary.CombatLosses(s.DiagnosticSnapshot(),s.Seconds),l=>Assert.True(l.At<=expiry));}
    [Fact]public void ForgedCombatTargetIsRejected(){var s=Ready();Permit(s);var w=s.DiagnosticSnapshot();var e=w.NewMilitary!.Events.Single(e=>e.Effect==MilitaryEffect.CombatPermission);w.Messaging.Messages=w.Messaging.Messages.Select(m=>m.Id==e.Message?m with{Body=m.Body.Replace("exercise:local-contact","org:hojo")}:m).ToArray();Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void HistoricalDefinitionsAreUnchanged(){var s=Ready();string hash=ContractJson.CanonicalHash(s.DiagnosticSnapshot().Definitions);Permit(s);Send(s,NewMilitaryAction.CombatStart);At(s,s.Seconds+3);Assert.Equal(hash,ContractJson.CanonicalHash(s.DiagnosticSnapshot().Definitions));}
    [Fact]public void MoraleCollapseDoesNotDeleteOfficerOrTroops(){var s=Ready();Permit(s);Send(s,NewMilitaryAction.CombatStart);At(s,s.Seconds+12);Assert.All(NewGameMilitary.OwnCombatReport(s.DiagnosticSnapshot(),s.Seconds),r=>{Assert.True(r.Morale<=25);Assert.True(r.Soldiers>0);});Assert.Equal(3,s.DiagnosticSnapshot().Units.Length);Assert.Equal(LifeState.Adult,s.DiagnosticSnapshot().Characters.Single(c=>c.Id==s.PlayerControl).Life);}
}
